#include "WorldAiCommandBatch.h"
#include "json.hpp"
#include <cmath>
#include <stdexcept>
#include <unordered_set>
namespace Silver::WorldEditor
{
namespace{using Json=nlohmann::json;constexpr std::size_t MaxBytes=2*1024*1024,MaxCommands=512;
Json Record(const WorldObjectRecord&r){return{{"type",r.Type},{"position",r.Position},{"rotation",r.Angle},{"scale",r.Scale},{"baselineOnly",r.BaselineOnly}};}
WorldObjectRecord Parse(const Json&j){WorldObjectRecord r;r.Type=j.value("type",static_cast<std::int16_t>(-1));r.Position=j.at("position").get<std::array<float,3>>();r.Angle=j.at("rotation").get<std::array<float,3>>();r.Scale=j.value("scale",0.0f);r.BaselineOnly=j.value("baselineOnly",false);ValidateRecord(r);return r;}}
std::vector<std::uint8_t> WorldAiCommandBatch::Encode()const{Json commands=Json::array();for(const auto&c:Commands)commands.push_back({{"id",c.Id},{"expected",Record(c.Expected)},{"desired",Record(c.Desired)}});Json root{{"schema",Schema},{"requestId",RequestId},{"mapId",MapId},{"worldNumber",WorldNumber},{"safety",Safety},{"commands",commands}};auto text=root.dump(2)+"\n";if(text.size()>MaxBytes)throw std::length_error("AI CommandBatch excede limite.");return{text.begin(),text.end()};}
WorldAiCommandBatch WorldAiCommandBatch::Decode(std::span<const std::uint8_t> bytes){if(bytes.empty()||bytes.size()>MaxBytes)throw std::invalid_argument("AI CommandBatch fuera de limites.");Json j;try{j=Json::parse(std::string(reinterpret_cast<const char*>(bytes.data()),bytes.size()));}catch(const Json::exception&){throw std::invalid_argument("AI CommandBatch JSON invalido.");}if(j.value("schema","")!=Schema)throw std::invalid_argument("AI CommandBatch schema incompatible.");WorldAiCommandBatch b;b.RequestId=j.value("requestId","");b.MapId=j.value("mapId",-1);b.WorldNumber=j.value("worldNumber",-1);b.Safety=j.value("safety","");if(b.RequestId.empty()||b.MapId<0||b.WorldNumber<0||b.Safety!="CANDIDATE_ONLY; NO_AUTO_APPLY"||!j.contains("commands")||!j.at("commands").is_array()||j.at("commands").size()>MaxCommands)throw std::invalid_argument("AI CommandBatch incompleto/inseguro.");std::unordered_set<ObjectId> ids;for(const auto&x:j.at("commands")){WorldAiObjectCommand c;c.Id=x.value("id",NoObject);c.Expected=Parse(x.at("expected"));c.Desired=Parse(x.at("desired"));if(c.Id==NoObject||!ids.insert(c.Id).second||c.Expected.Type!=c.Desired.Type||c.Expected.BaselineOnly!=c.Desired.BaselineOnly)throw std::invalid_argument("AI CommandBatch intenta cambiar identidad o duplica ID.");b.Commands.push_back(std::move(c));}return b;}
bool WorldAiCommandBatch::Validate(const WorldObjectDocument&document,std::string&error)const{for(const auto&c:Commands){const auto*live=document.Find(c.Id);if(!live){error="AI command referencia objeto inexistente.";return false;}if(!(*live==c.Expected)){error="AI command bloqueado: objeto cambio desde Expected.";return false;}if(c.Desired.BaselineOnly){error="AI command no puede editar registro baseline-only.";return false;}}error.clear();return true;}
bool WorldAiCommandBatch::Apply(WorldObjectDocument&document,std::string&error)const{if(!Validate(document,error))return false;std::vector<WorldObjectUpdate> updates;updates.reserve(Commands.size());for(const auto&c:Commands)updates.push_back({c.Id,c.Desired});if(updates.empty()){error="AI CommandBatch no contiene cambios.";return false;}if(!document.SetMany(updates,"Apply AI Command Batch")){error="AI CommandBatch no produjo cambios.";return false;}error.clear();return true;}
}
